// If classification fails for any reason, treat the message as a lead rather
// than dropping it. A false positive costs someone thirty seconds; a missed
// enquiry costs a job.
const msg = $('Verify Signature & Flatten').item.json;
const res = $json;

let parsed = null;
const textBlock = (res.content ?? []).find((b) => b.type === 'text');
if (!res.error && res.stop_reason !== 'refusal' && textBlock) {
  try {
    parsed = JSON.parse(textBlock.text);
  } catch {
    parsed = null;
  }
}

if (!parsed) {
  return {
    json: {
      ...msg,
      intent: 'lead',
      urgent: false,
      mentionsClaim: false,
      summary: 'Classification failed — routed to a human by default.',
      suggestedReply: '',
      actionable: true,
    },
  };
}

return {
  json: {
    ...msg,
    intent: parsed.intent,
    urgent: parsed.urgent === true,
    mentionsClaim: parsed.mentions_claim === true,
    summary: parsed.summary,
    suggestedReply: parsed.suggested_reply,
    actionable: ['lead', 'question', 'complaint'].includes(parsed.intent),
  },
};

