// Praise and spam stop here. Logged in the execution history, nothing else.
console.log(`Ignored ${$json.intent} from ${$json.authorName} on ${$json.platform}`);
return { json: $json };

// Meta signs the raw bytes of the body with the app secret, so hash exactly
// what arrived. With rawBody enabled the parsed object is in $json.body and
// the original bytes are in binary `data`; they are not interchangeable.
// Buffer is available in the Code sandbox even on Cloud, where crypto is not.
const bin = $input.item.binary?.data ?? null;

let raw = null;
if (bin?.data) {
  raw = Buffer.from(bin.data, 'base64').toString('utf8');
} else if (typeof $json.body === 'string') {
  raw = $json.body;
}

return {
  json: {
    raw: raw ?? '',
    rawMissing: raw === null,
    providedSignature: String($json.headers?.['x-hub-signature-256'] ?? ''),
  },
};
